function otherBookings(m){const current=new Set([...m.hotels.map(h=>'hotel.'+h.bookingId),...m.flights.map(f=>'flight.'+f.bookingId)]);const list=Object.entries(records).filter(([k,v])=>k.endsWith('.meta')&&!current.has(k.slice(0,-5))&&records[k.slice(0,-5)+'.status']!=='취소');if(!list.length)return '';return '<div class="section-gap"><h3>다른 일정에 기록한 실제 예약</h3><p class="fine">현재 안과 날짜가 다른 기록입니다. 유지·변경·취소 여부를 확인하세요.</p>'+list.map(([k,v])=>'<p class="fine">'+esc(v.name)+' · '+esc(v.start)+' → '+esc(v.end)+' · '+esc(records[k.slice(0,-5)+'.status']||'상태 미입력')+'</p>').join('')+'</div>'}
function bookings(m){return `${intro('04','예약과 경비','항공·숙소 예약과 예상 지출을 관리합니다.')}<div class="subnav">${[['flights','항공'],['hotels','숙소'],['budget','경비'],['return','귀국 동선']].map(([id,t])=>`<button data-booking-tab="${id}" aria-pressed="${bookingTab===id}">${t}</button>`).join('')}</div>${bookingTab==='flights'?flights(m):bookingTab==='hotels'?`<div class="hotel-list">${m.hotels.map(h=>hotelArticle(h,m)).join('')}</div><div class="section-gap"><h3>멤버십과 무료숙박 배분</h3><p class="fine">부부 각자 아코르 플래티넘·아코르플러스, 스테이플러스 총 4장. 혜택 적용 조건은 예약 시 확인합니다.</p>${TRIP.rules.map(([t,p])=>`<details><summary>${esc(t)}</summary><p>${esc(p)}</p></details>`).join('')}</div>`:bookingTab==='budget'?budget(m):returnOptions(m)}${otherBookings(m)}`}
function prep(m){const tasks=m.tasks.filter(t=>ownerFilter==='전체'||(ownerFilter==='미정'?!ownerOf(t):ownerOf(t)===ownerFilter)),groups=[...new Set(tasks.map(t=>t.group))];return `${intro('05','여행 준비','가족이 함께 준비할 일을 확인합니다.')}<div class="progress-panel"><svg class="progress-ring" viewBox="0 0 100 100" role="img" aria-label="준비 완료 ${m.progress}%"><circle cx="50" cy="50" r="40"/><circle class="progress" cx="50" cy="50" r="40" stroke-dasharray="251.33" stroke-dashoffset="${251.33*(1-m.progress/100)}"/><text x="50" y="57" text-anchor="middle">${m.progress}%</text></svg><div><h3>${m.tasks.filter(t=>t.done).length}개 완료 · ${m.tasks.filter(t=>!t.done).length}개 남음</h3></div></div><label class="owner-filter">담당자 필터<select id="owner-filter">${['전체','미정',...owners].map(o=>`<option ${ownerFilter===o?'selected':''}>${o}</option>`).join('')}</select></label><div class="prep-layout"><div>${groups.map(g=>{const list=tasks.filter(t=>t.group===g),due=list.find(t=>t.due)?.due;return `<section class="task-group"><div class="section-heading"><h3>${esc(g)}</h3>${due?`<span class="fine">${dateLabel(due)}까지</span>`:''}</div>${list.map(t=>`<div class="owned-task">${taskCheck(t)}<label class="owner-select"><span class="sr-only">${esc(t.text)} 담당자</span><select data-owner="${t.id}" aria-label="${esc(t.text)} 담당자"><option value="">미정</option>${owners.map(o=>`<option ${ownerOf(t)===o?'selected':''}>${o}</option>`).join('')}</select></label></div>`).join('')}</section>`}).join('')||'<p>해당 담당자의 준비사항이 없습니다.</p>'}</div><aside class="prep-aside"><h3>확인할 것</h3><ul>${m.risk.map(r=>`<li>${esc(r)}</li>`).join('')}</ul><div class="notes section-gap"><h3>가족 여행 메모</h3><textarea id="general-note" aria-label="가족 여행 메모">${esc(records['general.note']||'')}</textarea><button class="secondary" id="save-general">여행 메모 저장</button></div></aside></div>${emergencyCard()}`}
function emergencyCard(){const consulate=valueOf(records,'general.emergency.consulate',TRIP.emergency.consulate),insurance=valueOf(records,'general.emergency.insurance',TRIP.emergency.insurance);return `<section class="emergency-card"><div class="section-heading"><h2>비상정보</h2><button class="secondary" data-edit-emergency>연락처 수정</button></div><a class="emergency-number" href="tel:000"><span>호주 긴급번호</span><strong>000</strong><span>전화 걸기</span></a><dl><dt>주시드니 총영사관</dt><dd>${esc(consulate||'미정')}</dd><dt>여행자보험 연락처</dt><dd>${esc(insurance||'미정')}</dd></dl><p class="fine">저장한 HTML 사본에서도 확인할 수 있습니다.</p></section>`}
function render(){destroyMap();const focusTask=document.activeElement?.dataset?.task;let m=derive(selection,records);selection.day=m.day.date;$$('[data-plan]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.plan)===m.plan)));$$('[data-ret]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.ret===m.ret)));$('#early-wrap').hidden=m.plan!==1;$('#early').checked=m.early;$$('[data-page]').forEach(p=>p.hidden=p.id!==view);$$('[data-view]').forEach(a=>a.setAttribute('aria-current',a.dataset.view===view?'page':'false'));const renderers={cover:home,compare,itinerary,bookings,prep};$('#'+view).innerHTML=renderers[view](m);if(focusTask)$('[data-task=\"'+focusTask+'\"]')?.focus?.({preventScroll:true});const strip=$('.date-strip'),active=$('.date-btn[aria-pressed=true]');if(strip&&active)strip.scrollLeft=Math.max(0,active.offsetLeft-strip.offsetLeft-(strip.clientWidth-active.clientWidth)/2);$('#fx-input').value=m.fx;$('#membership-info').textContent=TRIP.memberships;updateSync();saveLocal();
 m=derive(selection,records);$('#plan-chip').textContent=`${m.plan}안 · ${m.ret==='brisbane'?'브리즈번':'시드니'} 귀국 ▾`;$('#mile-oz').value=records['general.mile.oz']||'';$('#mile-ke').value=records['general.mile.ke']||'';if(view==='itinerary'&&itineraryMode==='detail')initDayMap(m);
 $('#theme').innerHTML=themeIcon();$('#theme').setAttribute('aria-label',document.body.classList.contains('dark')?'라이트모드로 바꾸기':'다크모드로 바꾸기')}
function destroyMap(){clearTimeout(mapTimer);if(liveMap){liveMap.remove();liveMap=null}}
function initDayMap(m){const el=$('#trip-map');if(!el)return;const panel=el.closest('.map-panel');if(typeof L==='undefined'){panel.hidden=true;return}const points=[];const h=m.hotels.find(h=>h.id===m.day.hotel);if(h&&h.id!=='sydlast')points.push({xy:h.xy,name:h.short,hotel:true});for(const id of m.day.places){const p=TRIP.places[id];if(p?.xy)points.push({xy:p.xy,name:p.name})}if(!points.length){panel.hidden=true;return}try{const map=L.map(el,{scrollWheelZoom:false,attributionControl:true,zoomControl:true});liveMap=map;map.attributionControl.setPrefix(false);let loaded=0,failed=0;const hide=()=>{if(liveMap!==map)return;map.remove();liveMap=null;panel.hidden=true};const tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a>'});tiles.on('tileload',()=>loaded++);tiles.on('tileerror',()=>{failed++;if(!loaded&&failed>=2)hide()});tiles.addTo(map);points.forEach(p=>{const marker=L.marker([p.xy[1],p.xy[0]],{title:p.name,icon:L.divIcon({className:'location-marker '+(p.hotel?'hotel':'place'),html:`<span aria-hidden="true">${p.hotel?'숙':'●'}</span>`,iconSize:[44,44],iconAnchor:[22,22]})});marker.addTo(map).bindPopup(esc(p.name));});map.fitBounds(points.map(p=>[p.xy[1],p.xy[0]]),{padding:[35,35],maxZoom:14});mapTimer=setTimeout(()=>{if(!loaded)hide()},7000)}catch{panel.hidden=true}}
