function go(to){if(to==='today'){itineraryMode='detail';const m=derive(selection,records),tz=m.day.region==='골드코스트'||m.day.region==='브리즈번'?'Australia/Brisbane':'Australia/Sydney',now=new Intl.DateTimeFormat('en-CA',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());city='all';if(m.days.some(d=>d.date===now))selection.day=now;else toast('여행 기간 밖입니다. 선택한 날짜의 일정을 표시합니다.');to='itinerary'}view=validViews.includes(to)?to:'cover';history.replaceState(null,'','#'+view);render();window.scrollTo({top:0,behavior:'instant'})}
